//! Local acceptance gate for the converter's well-known gap-fill passes.
//!
//! The converted corpus (`tests/fixtures/converted/`) is `.gitignore`d
//! and regenerated by `bun run convert:all`; CI never has it, so every
//! test returns early when the directory is missing. The converter's own
//! `bun test` suite is the CI contract for the pass *logic* — this file
//! checks that the shape the pass writes survives conversion + loading,
//! i.e. that the shipped spec really completes the flag.
//!
//! Refs: docs/spec-conversion-policy.md, tools/ts-to-json/convert.ts
//! (`enrichGlobalOptions`, `enrichKnownArgGaps`).

use nerv_engine::spec_parser::{Generator, Opt, Subcommand};
use std::path::PathBuf;

fn converted(name: &str) -> Option<Subcommand> {
    let path: PathBuf = [env!("CARGO_MANIFEST_DIR"), "tests", "fixtures", "converted"]
        .iter()
        .collect::<PathBuf>()
        .join(format!("{name}.json"));
    if !path.is_file() {
        return None;
    }
    Some(
        nerv_engine::load_spec_file(&path)
            .unwrap_or_else(|e| panic!("loading {}: {e}", path.display())),
    )
}

fn opt<'a>(spec: &'a Subcommand, name: &str) -> &'a Opt {
    spec.options
        .iter()
        .find(|o| o.names.iter().any(|n| n == name))
        .unwrap_or_else(|| panic!("{} has no {name}", spec.name))
}

fn sub<'a>(spec: &'a Subcommand, path: &[&str]) -> &'a Subcommand {
    let mut cur = spec;
    for name in path {
        cur = cur
            .subcommands
            .iter()
            .find(|c| c.name == *name)
            .unwrap_or_else(|| panic!("{} has no subcommand {name}", cur.name));
    }
    cur
}

fn template_script(o: &Opt) -> &[String] {
    match &o.args[0].generators[0] {
        Generator::Template { script } => script,
        other => panic!("{} is not a template: {other:?}", o.names[0]),
    }
}

#[test]
fn kubectl_global_flags_are_persistent_and_sourced() {
    let Some(spec) = converted("kubectl") else {
        return;
    };
    for flag in ["--context", "--cluster", "--user", "--kubeconfig"] {
        let o = opt(&spec, flag);
        assert!(o.is_persistent, "{flag} must work after a subcommand");
        assert!(
            !o.args.is_empty() && !o.args[0].generators.is_empty(),
            "{flag} has no value source"
        );
    }
    assert_eq!(
        template_script(opt(&spec, "--context")),
        ["kubectl", "config", "get-contexts", "-o", "name"]
    );
    assert!(
        template_script(opt(&spec, "--cluster"))
            .iter()
            .any(|a| a.contains(".clusters[*]")),
        "cluster list comes from `kubectl config view` jsonpath"
    );
    assert!(
        matches!(
            opt(&spec, "--kubeconfig").args[0].generators[0],
            Generator::Filepaths { .. }
        ),
        "--kubeconfig is a path, not a command"
    );
}

#[test]
fn docker_global_context_is_sourced() {
    let Some(spec) = converted("docker") else {
        return;
    };
    let o = opt(&spec, "--context");
    assert!(o.is_persistent);
    assert_eq!(
        template_script(o),
        ["docker", "context", "ls", "--format", "{{.Name}}"]
    );
    // The lift is global: a subcommand that takes positional args still
    // parses `--context` (the spec tree itself is unchanged).
    assert!(!sub(&spec, &["run"]).args.is_empty());
}

fn gcloud_field(o: &Opt) -> &str {
    match &o.args[0].generators[0] {
        Generator::GcloudConfig { field } => field,
        other => panic!("{} is not gcloud_config: {other:?}", o.names[0]),
    }
}

#[test]
fn gcloud_global_flags_read_local_config() {
    let Some(spec) = converted("gcloud") else {
        return;
    };
    for (flag, field) in [
        ("--configuration", "configuration"),
        ("--project", "project"),
        ("--region", "region"),
        ("--zone", "zone"),
    ] {
        let o = opt(&spec, flag);
        assert!(o.is_persistent, "{flag} must work after a subcommand");
        assert_eq!(gcloud_field(o), field);
    }
}

#[test]
fn aws_region_and_output_are_static() {
    let Some(spec) = converted("aws") else {
        return;
    };
    let region = opt(&spec, "--region");
    assert!(region.is_persistent);
    assert!(
        region.args[0]
            .suggestions
            .iter()
            .any(|s| s.name == "us-east-1"),
        "--region must include us-east-1"
    );
    let output = opt(&spec, "--output");
    let names: Vec<_> = output.args[0]
        .suggestions
        .iter()
        .map(|s| s.name.as_str())
        .collect();
    assert_eq!(names, ["json", "yaml", "yaml-stream", "text", "table"]);
}
